(28954, 'Romans 3:26', 'Romans', 3, 26, 'دا د دې دپاره ؤ چې په دې زمانه کې خپل عدالت ښکاره کړي او دا ثابته کړي چې هغه په خپله عادل دی او هغه څوک عادل جوړوي چې په عیسی مسیح باندې ایمان راوړي.', 'دا د دې دپاره و چې په دې زمانه کې خپل عدالت شکاره کری او دا ثابته کری چې هغه په خپله عادل دی او هغه چوک عادل جوروی چې په عیسی مسیح باندې ایمان راوری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28955, 'Romans 3:27', 'Romans', 3, 27, 'نو بیا مونږ په څه باندې ویاړ وکړو؟ په هېڅ شي باندې نه. ایا په دې دلیل چې په شریعت باندې عمل کوو؟ نه، بلکې د ایمان په وسیله.', 'نو بیا مونز په چه باندې ویار وکرو؟ په هېچ شی باندې نه. ایا په دې دلیل چې په شریعت باندې عمل کوو؟ نه، بلکې د ایمان په وسیله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28956, 'Romans 3:28', 'Romans', 3, 28, 'ځکه مونږ پوهېږو چې د ایمان په وسیله عادل ګڼل کېږو، نه په شریعت باندې په عمل کولو سره.', 'جکه مونز پوهېزو چې د ایمان په وسیله عادل ګنل کېزو، نه په شریعت باندې په عمل کولو سره.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28957, 'Romans 3:29', 'Romans', 3, 29, 'ایا خدای یوازې د یهودیانو خدای دی؟ ایا هغه د غیریهودیانو خدای هم نه دی؟ بې له شکه چې دی.', 'ایا خدای یوازې د یهودیانو خدای دی؟ ایا هغه د غیریهودیانو خدای هم نه دی؟ بې له شکه چې دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28958, 'Romans 3:30', 'Romans', 3, 30, 'خدای یو دی او هغه خلک یوازې د ایمان په وسیله عادل جوړوي، که هغه یهودیان دي یا غیریهودیان.', 'خدای یو دی او هغه خلک یوازې د ایمان په وسیله عادل جوروی، که هغه یهودیان دی یا غیریهودیان.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(28959, 'Romans 3:31', 'Romans', 3, 31, 'ایا د دې معنی دا ده چې مونږ په دې ایمان باندې شریعت ایسته غورځوو؟ نه، هېڅکله نه، بلکې نور هم په هغه باندې ټینګ ودرېږو.', 'ایا د دې معنی دا ده چې مونز په دې ایمان باندې شریعت ایسته غورجوو؟ نه، هېچکله نه، بلکې نور هم په هغه باندې تینګ ودرېزو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_3_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
